// Verify the HMAC Nasaq signed the body with, then parse it.
//
// The signature covers the exact bytes that were sent, so it must be checked
// against the raw body — re-serialising the parsed JSON changes key order and
// whitespace and the digest with it. That is why the Webhook node has
// "Raw Body" switched on.
//
// Uses WebCrypto (the global `crypto`), which needs no n8n configuration.
// require('crypto') would also work but only with NODE_FUNCTION_ALLOW_BUILTIN=crypto.

const secret = $env.NASAQ_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('NASAQ_WEBHOOK_SECRET is not set on this n8n instance.');
}

const item = $input.first();

const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body || item.json);

const headers = item.json.headers || {};
const given = headers['x-nasaq-signature'] || '';

const encoder = new TextEncoder();
const key = await crypto.subtle.importKey(
  'raw',
  encoder.encode(secret),
  { name: 'HMAC', hash: 'SHA-256' },
  false,
  ['sign'],
);
const signed = await crypto.subtle.sign('HMAC', key, encoder.encode(raw));
const expected =
  'sha256=' +
  Array.from(new Uint8Array(signed))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');

// Length first: comparing strings of different lengths is not the interesting
// case, and this keeps the comparison itself constant-time.
let valid = given.length === expected.length;
if (valid) {
  let diff = 0;
  for (let i = 0; i < given.length; i++) {
    diff |= given.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  valid = diff === 0;
}

return [{ json: { valid, payload: JSON.parse(raw) } }];

// Turn the event into the one number and one block of Arabic text that
// Evolution API needs.
//
// This node is the whole reason Nasaq posts an event instead of calling
// Evolution itself: the wording below is the school's, and changing it is an
// edit here, not a backend deploy.

// `payload` is what the Verify node hands over. The fallback lets this node be
// run on its own with pinned data.
const p = $json.payload || $json;
const r = p.recipient || {};

// The frontend has one login route and no school in the path — the school is
// resolved from the account, not the URL. Building `${base}/${slug}` gives a
// link that 404s.
const portalBase = ($env.NASAQ_PORTAL_URL || 'https://nasaq.185.170.196.120.sslip.io')
  .replace(/\/$/, '');
const portal = `${portalBase}/login`;

const school = p.school || {};
const who = r.role === 'TEACHER' ? 'المعلم/ة' : 'الطالب/ة';

let text;

if (p.event === 'credentials.test') {
  text =
    `✅ *${school.name}*\n\n` +
    'رسالة اختبار من نظام نسق. الربط مع واتساب يعمل بنجاح.';
} else if (p.reason === 'password_reset') {
  text =
    `*${school.name}*\n\n` +
    `تم تعيين كلمة مرور جديدة لحساب ${who}: ${r.name}\n\n` +
    `🔗 رابط الدخول: ${portal}\n` +
    `📧 اسم المستخدم: ${r.loginEmail}\n` +
    `🔑 كلمة المرور الجديدة: ${r.password}\n\n` +
    'يُرجى تغيير كلمة المرور بعد تسجيل الدخول.\n' +
    'إذا لم تطلب ذلك، تواصل مع إدارة المدرسة فورًا.\n\n' +
    '_رسالة آلية، برجاء عدم الرد عليها._';
} else {
  text =
    `مرحبًا بك في *${school.name}* 👋\n\n` +
    `تم إنشاء حساب ${who}: ${r.name}\n\n` +
    `🔗 رابط الدخول: ${portal}\n` +
    `📧 اسم المستخدم: ${r.loginEmail}\n` +
    `🔑 كلمة المرور: ${r.password}\n\n` +
    'يُرجى تغيير كلمة المرور بعد أول تسجيل دخول.\n\n' +
    '_رسالة آلية، برجاء عدم الرد عليها._';
}

return [
  {
    json: {
      eventId: p.eventId,
      number: r.phone,
      text,
    },
  },
];
